def validate_yaralite(self, target_dir: str) -> dict:
    """Validate the project YARA-lite rules file.

    Args:
        target_dir: Project root directory.

    Returns:
        Validation payload with rule counts and errors.
    """
    candidate = Path(target_dir).resolve() / self._config.YARALITE_RULES_FILE
    if not candidate.is_file():
        return {"valid": False, "rule_count": 0, "rules": [], "tiers": {}, "errors": ["no rules file"]}
    return validate_yaralite_rules(candidate.read_text(encoding="utf-8"))

def _site_stats(
    nodes: List[Node], edges: List[Edge], analysis: Optional[AnalysisResult],
) -> Dict[str, int]:
    """Return headline counters for the gallery (imports exclude call edges)."""
    return {
        "files": len(nodes),
        "symbols": sum(len(n.symbols) for n in nodes),
        "imports": sum(1 for e in edges if e.relation == "imports"),
        "languages": len({n.language for n in nodes}),
        "communities": len(analysis.communities) if analysis else 0,
    }

def _read_contents(self, root: Path, nodes: List[Node]) -> Dict[str, str]:
    """Re-read scanned file contents, skipping symlinks and oversized files.

    Args:
        root: Project root directory.
        nodes: Scanned file nodes.

    Returns:
        Mapping of file id to text content.
    """
    content_map: Dict[str, str] = {}
    max_bytes = int(self._config.MAX_FILE_SIZE_MB * 1024 * 1024)
    for node in nodes:
        path = root / node.node_id
        try:
            if not path.is_file() or path.is_symlink():
                continue
            if max_bytes and path.stat().st_size > max_bytes:
                continue
            content_map[node.node_id] = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
    return content_map

def _memory_notes(self, root: Path) -> List[Tuple[str, str, str]]:
    """Session-log notes from MEMORY.md as (date, kind, text) triples."""
    if not self._config.MEMORY_ENABLED:
        return []
    return [(n.date, n.kind, n.text) for n in self._factory.memory.notes(str(root))]

def watch(self, target_dir: str) -> None:
    from readmenator._watcher import DirectoryWatcher
    root = str(Path(target_dir).resolve())

def audit_deep(self, target_dir: str) -> AnalysisResultV2:
    nodes, edges, content_map = self._scan_with_content(target_dir)
    resolved_edges = self._last_resolved_edges
    layers = LayerDetector().detect(nodes, edges)
    result = self._deep_runner.run(nodes, edges, resolved_edges, layers, content_map)
    if result.taint:
        logger.info("Taint paths: %d", len(result.taint.paths))
    if result.cycles:
        logger.info("Dependency cycles: %d", len(result.cycles))
    if result.hotspots:
        logger.info(
            "Top hotspot: %s",
            result.hotspots[0].file_id if result.hotspots else "none",
        )
    if result.layer_violations:
        logger.info("Layer violations: %d", len(result.layer_violations))
    if result.suggested_rules:
        logger.info("Suggested rules: %d", len(result.suggested_rules))
    return result

def load(self) -> Dict[str, str]:
    if not self._cache_path.is_file():
        return {}
    try:
        data = json.loads(self._cache_path.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return data
    except (json.JSONDecodeError, OSError):
        pass
    return {}

def save(self, hashes: Dict[str, str]) -> None:
    self._cache_dir.mkdir(parents=True, exist_ok=True)
    self._cache_path.write_text(
        json.dumps(hashes, indent=2, sort_keys=True), encoding="utf-8"
    )

def compute_hash(self, file_path: Path) -> str:
    hasher = hashlib.sha256()
    try:
        data = file_path.read_bytes()
        hasher.update(data)
    except OSError:
        return ""
    return hasher.hexdigest()

def compute_hashes(self, file_paths: Dict[str, Path]) -> Dict[str, str]:
    result: Dict[str, str] = {}
    for rel_path, abs_path in file_paths.items():
        h = self.compute_hash(abs_path)
        if h:
            result[rel_path] = h
    return result

def find_changed(self, file_paths: Dict[str, Path]) -> Set[str]:
    cached = self.load()
    changed: Set[str] = set()
    for rel_path, abs_path in file_paths.items():
        if rel_path not in cached:
            changed.add(rel_path)
            continue
        current_hash = self.compute_hash(abs_path)
        if current_hash and current_hash != cached[rel_path]:
            changed.add(rel_path)
    return changed

def prune_deleted(self, current_file_ids: Set[str]) -> None:
    cached = self.load()
    pruned = {k: v for k, v in cached.items() if k in current_file_ids}
    if len(pruned) != len(cached):
        self.save(pruned)
        self._prune_analysis_cache(current_file_ids)

# ------------------------------------------------------------------
# Analysis result caching (semantic cache)
# ------------------------------------------------------------------

def save_analysis(
    self,
    key: str,
    data: Dict[str, Any],
) -> None:
    """Save an analysis result to the semantic cache.

    Args:
        key: Cache key (e.g. "security", "analysis_v2", "taint").
        data: Serializable analysis data.
    """
    self._cache_dir.mkdir(parents=True, exist_ok=True)
    cache: Dict[str, Any] = {}
    if self._analysis_cache_path.is_file():
        try:
            cache = json.loads(self._analysis_cache_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            pass
    cache[key] = data
    self._analysis_cache_path.write_text(
        json.dumps(cache, indent=2, default=str), encoding="utf-8"
    )

def load_analysis(self, key: str) -> Optional[Dict[str, Any]]:
    """Load a previously cached analysis result.

    Args:
        key: Cache key.

    Returns:
        Cached data dict, or None if not found or expired.
    """
    if not self._analysis_cache_path.is_file():
        return None
    try:
        cache = json.loads(self._analysis_cache_path.read_text(encoding="utf-8"))
        return cache.get(key)
    except (json.JSONDecodeError, OSError):
        return None

def clear_analysis(self, key: Optional[str] = None) -> None:
    """Clear analysis cache, optionally for a specific key only.

    Args:
        key: If given, only clears this key. Otherwise clears all.
    """
    if not self._analysis_cache_path.is_file():
        return
    try:
        if key is None:
            self._analysis_cache_path.unlink(missing_ok=True)
        else:
            cache = json.loads(self._analysis_cache_path.read_text(encoding="utf-8"))
            cache.pop(key, None)
            self._analysis_cache_path.write_text(
                json.dumps(cache, indent=2, default=str), encoding="utf-8"
            )
    except (json.JSONDecodeError, OSError):
        pass

def _prune_analysis_cache(self, current_file_ids: Set[str]) -> None:
