def _origin(self, project_root: str) -> str:
    """Return the main repository URL via ``gh`` or ``git remote``."""
    attempts: Sequence[List[str]] = (
        ["gh", "repo", "view", "--json", "url", "--jq", ".url"],
        ["git", "remote", "get-url", self._config.GH_WIKI_GIT_REMOTE_NAME],
    )
    for command in attempts:
        out = self._call(command, cwd=project_root)
        if out is not None and _REMOTE_RE.match(out.strip()):
            return out.strip()
    return ""

def _call(self, command: List[str], cwd: str) -> Optional[str]:
    """Run a command without a shell and return stdout, or None on failure."""
    try:
        result = self._run(
            command, cwd=cwd, capture_output=True, text=True,
            timeout=self._config.GH_WIKI_TIMEOUT_S, check=False,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if result.returncode != 0:
        logger.debug("Command failed (%s): %s", result.returncode, " ".join(command))
        return None
    return result.stdout or ""

def _write_pages(self, target: Path, pages: Dict[str, str]) -> List[str]:
    """Write pages, delete stale previously generated ones, and record state."""
    state = target / self._config.GH_WIKI_STATE_FILE
    previous: List[str] = []
    if state.is_file() and not state.is_symlink():
        previous = [
            line.strip() for line in state.read_text(encoding="utf-8").splitlines()
            if line.strip().endswith(".md") and "/" not in line
        ]
    removed: List[str] = []
    for name in previous:
        stale = target / name
        if name not in pages and stale.is_file() and not stale.is_symlink():
            stale.unlink()
            removed.append(name)
    for name, content in pages.items():
        (target / name).write_text(content, encoding="utf-8")
    state.write_text("\n".join(sorted(pages)) + "\n", encoding="utf-8")
    return removed

def _read_small(path: Path) -> str:
    """Return the stripped text of a small regular file, or empty string.

    Args:
        path: File to read.

    Returns:
        File contents, or empty string when missing, a symlink, or oversized.
    """
    try:
        if path.is_symlink() or not path.is_file():
            return ""
        if path.stat().st_size > _MAX_META_BYTES:
            return ""
        return path.read_text(encoding="utf-8", errors="ignore").strip()
    except OSError:
        return ""

def _packed_ref(git_dir: Path, ref: str) -> str:
    """Look up a ref in packed-refs, honoring worktree commondir.

    Args:
        git_dir: Git directory of the work tree.
        ref: Fully qualified ref name.

    Returns:
        The commit hash, or empty string.
    """
    candidates = [git_dir]
    common = _read_small(git_dir / "commondir")
    if common:
        candidates.append((git_dir / common).resolve())
    for base in candidates:
        loose = _read_small(base / ref)
        if loose:
            return loose
        for line in _read_small(base / "packed-refs").splitlines():
            parts = line.split(" ", 1)
            if len(parts) == 2 and parts[1].strip() == ref:
                return parts[0].strip()
    return ""

def read_git_head(project_root: str) -> Dict[str, str]:
    """Return the current commit and branch of a project, when available.

    Args:
        project_root: Work tree root directory.

    Returns:
        Mapping with ``commit`` and ``branch`` keys (empty strings when
        unknown or not a git repository).
    """
    git_dir = _git_dir(Path(project_root).resolve())
    if git_dir is None:
        return {"commit": "", "branch": ""}
    head = _read_small(git_dir / "HEAD")
    if head.startswith(_REF_PREFIX):
        ref = head[len(_REF_PREFIX):].strip()
        branch = ref[len(_HEADS_PREFIX):] if ref.startswith(_HEADS_PREFIX) else ref
        return {"commit": _packed_ref(git_dir, ref), "branch": branch}
    return {"commit": head, "branch": ""}

def _snapshot_steps(iterations: int, snapshots: int) -> List[int]:
    """Iteration indices at which to record snapshots (always includes 0 and the last)."""
    count = max(2, snapshots)
    return sorted({round(i * iterations / (count - 1)) for i in range(count)})

def interpolate_frames(frames: List[Dict[str, Point]], t: float) -> Dict[str, Point]:
    """Linear interpolation between snapshots for a progress t in [0, 1]."""
    if not frames:
        return {}
    if len(frames) == 1 or t >= 1.0:
        return dict(frames[-1])
    t = max(0.0, t)
    pos = t * (len(frames) - 1)
    i = int(pos)
    f = pos - i
    a, b = frames[i], frames[min(i + 1, len(frames) - 1)]
    return {nid: (a[nid][0] + (b[nid][0] - a[nid][0]) * f, a[nid][1] + (b[nid][1] - a[nid][1]) * f) for nid in a}


@dataclass(frozen=True)

def _unit(v: Sequence[float]) -> Point3:
    """Normalize a 3D vector (zero vectors map to the north pole)."""
    norm = math.sqrt(sum(c * c for c in v))
    if norm < 1e-12:
        return (0.0, -1.0, 0.0)
    return (v[0] / norm, v[1] / norm, v[2] / norm)


@dataclass(frozen=True)

def _undirected_weights(groups: Dict[str, List[str]], edges: Sequence[Tuple[str, str]]) -> Tuple[Dict[Tuple[str, str], int], Dict[str, List[str]]]:
    """Return group-pair edge counts and per-member neighbour lists.

    Args:
        groups: Group label to member ids.
        edges: Directed (source, target) pairs; unknown ids and self loops skipped.

    Returns:
        Tuple of (sorted group pair to count, member to sorted neighbour ids).
    """
    member_group = {m: g for g, ms in groups.items() for m in ms}
    pair_weight: Dict[Tuple[str, str], int] = {}
    neighbours: Dict[str, set] = {m: set() for m in member_group}
    for a, b in edges:
        if a == b or a not in member_group or b not in member_group:
            continue
        neighbours[a].add(b)
        neighbours[b].add(a)
        ga, gb = member_group[a], member_group[b]
        if ga != gb:
            key = (ga, gb) if ga < gb else (gb, ga)
            pair_weight[key] = pair_weight.get(key, 0) + 1
    return pair_weight, {m: sorted(ns) for m, ns in neighbours.items()}

def _angular_distance(a: float, b: float) -> float:
    """Return the shortest angular distance between two angles in radians."""
    d = abs(a - b) % (2 * math.pi)
    return min(d, 2 * math.pi - d)

def _center_out(members: List[str]) -> List[str]:
    """Reorder a ranked list so the first item sits in the middle, then alternate outwards."""
    left: List[str] = []
    right: List[str] = []
    for pos, member in enumerate(members):
        if pos % 2 == 0:
            right.append(member)
        else:
            left.append(member)
    return list(reversed(left)) + right

def _group_order_cost(order: List[str], sizes: Dict[str, int], weights: Dict[Tuple[str, str], int], gap: float) -> float:
    """Weighted angular distance between group arc centers for one cyclic order."""
    total_members = sum(sizes[g] for g in order) or 1
    usable = 2 * math.pi - gap * len(order)
    step = usable / total_members
    mids: Dict[str, float] = {}
    angle = 0.0
    for label in order:
        span = sizes[label] * step
        mids[label] = angle + span / 2
        angle += span + gap
    return sum(w * _angular_distance(mids[a], mids[b]) for (a, b), w in weights.items())

def chord_total(leaves: Dict[str, Point3]) -> float:
    """Sum of straight-line edge lengths."""
    total = 0.0
    for a, b in edges:
        if a in leaves and b in leaves and a != b:
            pa, pb = leaves[a], leaves[b]
            total += math.sqrt(sum((pa[k] - pb[k]) ** 2 for k in range(3)))
    return total

current = dict(layout.leaves)
best = chord_total(current)
for _ in range(max(0, sweeps)):
    proposal = dict(current)
    for label, members in groups.items():
        if not members or label not in centers:
            continue
        free = [current[m] for m in members if m in current]
        order = sorted(members, key=lambda m: (-len(neighbours.get(m, [])), members.index(m)))
        for member in order:
            ns = [current[n] for n in neighbours.get(member, []) if n in current]
            if ns:
                target = _unit([sum(p[k] for p in ns) for k in range(3)])
            else:
