            pick = max(range(len(free)), key=lambda i: (sum(free[i][k] * target[k] for k in range(3)), -i))
            proposal[member] = free.pop(pick)
    value = chord_total(proposal)
    if value < best - 1e-12:
        current, best = proposal, value
    else:
