    impact = 0
    for edge in resolved_edges:
        if edge.target == file_id:
            impact += 1
    return impact

def _build_stem_index(self, file_ids: List[str]) -> Dict[str, List[str]]:
    """Map file stems (without extension) to their full paths."""
    index: Dict[str, List[str]] = {}
    for fid in file_ids:
        stem = Path(fid).stem
        if stem not in index:
            index[stem] = []
        index[stem].append(fid)
    return index

def _build_dir_index(self, file_ids: List[str]) -> Dict[str, Set[str]]:
    """Map directory paths to the files they contain."""
    index: Dict[str, Set[str]] = {}
    for fid in file_ids:
        parent = str(Path(fid).parent)
        if parent not in index:
            index[parent] = set()
        index[parent].add(fid)
    for key in list(index.keys()):
        parts = key.split("/") if key != "." else []
        for i in range(1, len(parts) + 1):
            prefix = "/".join(parts[:i])
            if prefix not in index:
                index[prefix] = set()
            index[prefix].update(index[key])
    return index

def _resolve_relative(self, import_str: str, source_file: str) -> Optional[str]:
    """Resolve a relative import (starts with ``.`` or ``..``)."""
    if not import_str.startswith("."):
        return self._resolve_verbatim(import_str, source_file)
    source_dir = str(Path(source_file).parent) if source_file else ""
    base = Path(source_dir) if source_dir != "." else Path("")
    candidate_path = posixpath.normpath((base / import_str).as_posix())
    if candidate_path in self._file_ids:
        return candidate_path
    for ext in self._extensions:
        with_ext = candidate_path + ext
        if with_ext in self._file_ids:
            return with_ext
    init_path = f"{candidate_path}/__init__.py"
    if init_path in self._file_ids:
        return init_path
    return None

def _resolve_verbatim(self, import_str: str, source_file: str) -> Optional[str]:
    """Resolve a path-like import verbatim against the source directory.

    Covers quoted C-family includes such as ``"utils.h"`` or
    ``"lib/net.h"`` which name a project file relative to the
    including file.
    """
    source_dir = str(Path(source_file).parent) if source_file else ""
    if "/" not in import_str and "." not in import_str:
        return None
    if source_dir and source_dir != ".":
        candidate = posixpath.normpath(f"{source_dir}/{import_str}")
    else:
        candidate = posixpath.normpath(import_str)
    if candidate in self._file_ids:
        return candidate
    return None

def _resolve_extensionless(self, import_str: str, source_file: str) -> Optional[str]:
    """Resolve a bare module name by appending known extensions."""
    source_dir = str(Path(source_file).parent) if source_file else ""
    for ext in self._extensions:
        candidate = f"{source_dir}/{import_str}{ext}" if source_dir and source_dir != "." else f"{import_str}{ext}"
        if candidate in self._file_ids:
            return candidate
    return None

def _resolve_directory_init(self, import_str: str, source_file: str) -> Optional[str]:
    """Resolve as a package directory with __init__ or index file."""
    source_dir = str(Path(source_file).parent) if source_file else ""
    base = f"{source_dir}/{import_str}" if source_dir and source_dir != "." else import_str
    for init_name in ("__init__.py", "index.js", "index.ts", "mod.rs", "lib.rs"):
        candidate = f"{base}/{init_name}"
        if candidate in self._file_ids:
            return candidate
    return None

def _resolve_module_dotpath(self, import_str: str) -> Optional[str]:
    """Resolve a dotted module path (Python/Java convention)."""
    if "." not in import_str:
        return None
    if import_str.startswith("."):
        return None
    parts = import_str.split(".")
    if any(p in self._PYTHON_STDLIB for p in parts[:1]):
        return None
    candidate_path = "/".join(parts)
    candidates = [
        f"{candidate_path}.py",
        f"{candidate_path}/__init__.py",
        f"{candidate_path}.js",
        f"{candidate_path}/index.js",
        candidate_path,
    ]
    for candidate in candidates:
        if candidate in self._file_ids:
            return candidate
    return None

def __init__(self, config: Config) -> None:
    self._config = config
    self._rule_counter: int = 0

def write_rules(
    self, rules: List[SuggestedRule], output_dir: str
) -> int:
    """Write suggested rules to Semgrep YAML files in output_dir.

    Returns the number of rule files written.
    """
    out = Path(output_dir)
    out.mkdir(parents=True, exist_ok=True)
    written = 0

    rule_groups: Dict[str, List[SuggestedRule]] = {}
    for rule in rules:
        if rule.language not in rule_groups:
            rule_groups[rule.language] = []
        rule_groups[rule.language].append(rule)

    for lang, lang_rules in rule_groups.items():
        filepath = out / f"readmenator_{lang}.yml"
        yaml_parts: List[str] = ["# ReadMenator suggested rules for " + lang, "# Generated by readmenator rule generator", ""]
        for rule in lang_rules:
            if rule.semgrep_yaml:
                yaml_parts.append(rule.semgrep_yaml)
                yaml_parts.append("")
        if len(yaml_parts) > 3:
            filepath.write_text("\n".join(yaml_parts), encoding="utf-8")
            written += 1

    rules_yaml: List[str] = ["# ReadMenator suggested rules (combined)", "# Generated by readmenator rule generator", ""]
    for rule in rules:
        if rule.semgrep_yaml:
            rules_yaml.append(rule.semgrep_yaml)
            rules_yaml.append("")
    combined_path = out / "readmenator_all.yml"
    combined_path.write_text("\n".join(rules_yaml), encoding="utf-8")
    written += 1

    return written

def _group_by_language(self, nodes: List[Node]) -> Dict[str, List[Node]]:
    """Group nodes by their language extension."""
    groups: Dict[str, List[Node]] = {}
    for node in nodes:
        lang = node.language if node.language else "unknown"
        if lang not in groups:
            groups[lang] = []
        groups[lang].append(node)
    return groups

def _infer_language_for_rule(rule_id: str) -> str:
    """Infer target language for a built-in antipattern rule."""
    lang_map: Dict[str, str] = {
        "bare_except": "python",
        "print_statement": "python",
        "todo_comment": "multi",
        "hardcoded_password": "multi",
    }
    return lang_map.get(rule_id, "multi")

def export(
    self,
    findings: List[SecurityFinding],
    project_name: str = "readmenator",
) -> str:
    """Generate a SARIF v2.1.0 JSON string from security findings.

    Args:
        findings: List of SecurityFinding instances.
        project_name: Name of the scanned project for metadata.

    Returns:
        SARIF JSON string.
    """
    tool_rules: List[Dict] = []
    results: List[Dict] = []
    rule_ids: Dict[str, int] = {}

    for finding in findings:
        if finding.rule_id not in rule_ids:
            rule_ids[finding.rule_id] = len(rule_ids)
            tool_rules.append(self._build_rule(finding))

        result = self._build_result(finding, rule_ids[finding.rule_id])
        results.append(result)

    log = {
        "$schema": self.SARIF_SCHEMA,
        "version": self.SARIF_VERSION,
        "runs": [
            {
                "tool": {
                    "driver": {
                        "name": "ReadMenator",
                        "version": "1.0",
                        "informationUri": "https://github.com/grisuno/ReadMenator",
                        "rules": tool_rules,
                    }
                },
                "results": results,

def _build_rule(self, finding: SecurityFinding) -> Dict:
    """Build a SARIF reportingDescriptor (rule) object."""
    return {
        "id": finding.rule_id,
        "name": finding.rule_id,
        "shortDescription": {
            "text": finding.description,
        },
        "fullDescription": {
            "text": finding.description,
        },
        "defaultConfiguration": {
            "level": self.SEVERITY_LEVEL_MAP.get(
                finding.severity, "warning"
            ),
        },
        "properties": {
            "securitySeverity": finding.severity,
            "cwe": finding.cwe,
            "precision": "high",
            "tags": ["security", finding.severity],
        },
    }

def _build_result(self, finding: SecurityFinding, rule_index: int) -> Dict:
    """Build a SARIF result object for a single finding."""
    result: Dict = {
        "ruleId": finding.rule_id,
        "ruleIndex": rule_index,
        "level": self.SEVERITY_LEVEL_MAP.get(finding.severity, "warning"),
        "message": {
            "text": finding.description,
        },
        "locations": [
            {
                "physicalLocation": {
                    "artifactLocation": {
                        "uri": finding.file_path,
                        "uriBaseId": "%SRCROOT%",
                    },
                    "region": {
                        "startLine": finding.line,
                    },
                }
            }
        ],
    }

    if finding.snippet and not self._privacy_mode:
        result["locations"][0]["physicalLocation"]["region"]["snippet"] = {
            "text": finding.snippet,
        }

    if finding.cwe:
        result["properties"] = {
            "cwe": finding.cwe,
        }

    return result

def _is_ignored(self, path: Path) -> bool:
    """Return ``True`` if any path component matches IGNORE_DIRS."""
    if self._config.SCAN_MODE == "all":
        always = {".git", "__pycache__", ".pytest_cache", ".readmenator_cache"}
        return any(part in always for part in path.parts)
    return any(part in self._config.IGNORE_DIRS for part in path.parts)

def _load_gitignore(self, root: Path) -> None:
    """Parse .gitignore patterns using regex (no external deps)."""
    gitignore_path = root / ".gitignore"
    if not gitignore_path.is_file():
        self._gitignore_patterns = []
        return
    try:
        patterns: List[str] = []
        for line in gitignore_path.read_text(encoding="utf-8", errors="ignore").split("\n"):
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if stripped.startswith("!"):
                continue
            regex_pattern = self._gitignore_glob_to_regex(stripped)
            if regex_pattern:
                patterns.append(regex_pattern)
        self._gitignore_patterns = [re.compile(p) for p in patterns]
    except (OSError, re.error):
        self._gitignore_patterns = []

@staticmethod

def _gitignore_glob_to_regex(pattern: str) -> str:
    """Convert a .gitignore glob pattern to a regex pattern."""
    if pattern.startswith("/"):
        pattern = pattern[1:]
    if pattern.endswith("/"):
        pattern = pattern.rstrip("/")
    regex_parts: List[str] = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex_parts.append(".*")
                i += 2
                if i < len(pattern) and pattern[i] == "/":
                    i += 1
                continue
            else:
                regex_parts.append("[^/]*")
                i += 1
        elif c == "?":
            regex_parts.append("[^/]")
            i += 1
        elif c == ".":
            regex_parts.append("\\.")
            i += 1
        elif c == "[":
            end = pattern.find("]", i)
            if end == -1:
                regex_parts.append(re.escape(c))
                i += 1
            else:
                regex_parts.append(pattern[i:end + 1])
                i = end + 1
        else:
            regex_parts.append(re.escape(c))
            i += 1
    result = "".join(regex_parts)
    return f"(^|/){result}"

def _is_gitignored(self, rel_path: str) -> bool:
    """Check if a relative path matches any .gitignore pattern."""
    if not self._gitignore_patterns:
        return False
    for pattern in self._gitignore_patterns:
        if pattern.search(rel_path):
            return True
    return False

def _validate_path_security(self, path: Path) -> bool:
    """Reject symlinks and files exceeding MAX_FILE_SIZE_MB."""
    try:
        if path.is_symlink():
            return False
        if path.is_file():
            size_mb = path.stat().st_size / (1024.0 * 1024.0)
            if size_mb > self._config.MAX_FILE_SIZE_MB:
                return False
        return True
    except OSError:
        return False

def _check_directory_depth(self, path: Path, root: Path) -> bool:
    """Return ``True`` if *path* is within MAX_DIRECTORY_DEPTH of *root*."""
    try:
        rel_path = path.relative_to(root)
        return len(rel_path.parts) <= self._config.MAX_DIRECTORY_DEPTH
    except ValueError:
        return False

def scan_with_content(
    self, root: Path
) -> Tuple[List[Node], List[Edge], Dict[str, str]]:
    """Scan and also return raw file contents for deeper analysis.

    Returns:
        Tuple of (nodes, edges, content_map) where content_map maps
        node_id to raw file content.
    """
    return self._scan_impl(root)

def _scan_impl(
    self, root: Path
) -> Tuple[List[Node], List[Edge], Dict[str, str]]:
    """Internal scan implementation returning nodes, edges, and content."""
    nodes: List[Node] = []
    edges: List[Edge] = []
    content_map: Dict[str, str] = {}

    if not root.is_dir():
        raise ValueError(f"Path is not a valid directory: {root}")

    root = root.resolve()
    privacy = self._config.PRIVACY_MODE

    if self._config.GITIGNORE_AWARE:
        self._load_gitignore(root)

    scanned_count = 0
    skip_counts: Dict[str, int] = {
        "security": 0, "ignored_dir": 0, "gitignored": 0,
        "depth": 0, "unsupported_ext": 0, "parse_error": 0,
        "generated": 0,
    }
    gitignored_examples: List[str] = []

    for file_path in sorted(root.rglob("*")):
        if not file_path.is_file():
            continue

        if not self._validate_path_security(file_path):
            skip_counts["security"] += 1
            continue

        rel_path = file_path.relative_to(root)
        if self._is_ignored(rel_path):
            skip_counts["ignored_dir"] += 1
            continue

        if self._is_generated(rel_path):
            skip_counts["generated"] += 1

def _unquote(s: str) -> str:
    s = s.strip()
    if len(s) >= 2 and s[0] in ('"', "'") and s[0] == s[-1]:
        return s[1:-1]
    return s

def _load_rules_from_yaml(yaml_path: Path) -> list[dict] | None:
    """Load rule dicts from the YAML rules file, or return None on failure."""
    try:
        text = yaml_path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None

    parsed = _parse_minimal_yaml(text)
    if not parsed:
        return None

    # discard non-rule entries (like the comment block before `rules:`)
    if isinstance(parsed, list) and len(parsed) == 1 and "rule_id" not in parsed[0]:
        return None

    return parsed


# ── Built-in fallback rules (when YAML file is unavailable) ─────────────

def _compile(*patterns: str) -> re.Pattern:
    joined = "|".join(f"(?:{p})" for p in patterns)
    return re.compile(joined, re.IGNORECASE)

def _build_rules_from_yaml(yaml_path: Path) -> Dict[str, List[SecurityRule]] | None:
    """Attempt to build the rule map from the YAML rules file.

    Returns None if the YAML file cannot be loaded or parsed, allowing
    the caller to fall back to built-in rules.
    """
    raw_rules = _load_rules_from_yaml(yaml_path)
    if raw_rules is None:
        return None

    ext_map: Dict[str, List[SecurityRule]] = {}
    for raw in raw_rules:
        try:
            rule_id = raw.get("rule_id", "")
            severity = raw.get("severity", "medium")
            description = raw.get("description", "")
            cwe = raw.get("cwe", "")
            mitre = raw.get("mitre_attack", "")
            patterns: list = raw.get("patterns", [])
            extensions: list = raw.get("extensions", [])

            if not patterns or not extensions:
                continue

            pattern = _compile(*patterns)
            rule = SecurityRule(rule_id, severity, description, pattern, cwe, mitre)

            for ext in extensions:
                ext_map.setdefault(ext, []).append(rule)
        except (KeyError, TypeError, re.error):
            continue

    if not ext_map:
        return None
    return ext_map


