def _edge_call_sites(self, edges: List[Edge]) -> List[CallSite]:
    """Convert parser ``calls`` edges to line-less call sites."""
    sites: List[CallSite] = []
    for edge in edges:
        if edge.relation != "calls":
            continue
        caller = ""
        if "::" in edge.source:
            caller = edge.source.split("::", 1)[1]
            file_id = edge.source.split("::", 1)[0]
        else:
            file_id = edge.source
        callee = edge.target.split("::")[-1].split(".")[-1]
        if file_id and callee:
            sites.append(CallSite(file=file_id, caller=caller, callee=callee))
    return sites

def _push(self, node: ast.AST) -> None:
    """Record a scope entry by node name."""
    name = getattr(node, "name", "")
    if name:
        stack.append(str(name))

def _pop(self, node: ast.AST) -> None:
    """Leave the current scope when named."""
    if getattr(node, "name", "") and stack:
        stack.pop()

def _regex_call_sites(
    self, file_id: str, content: str, symbols: List[SymbolDef]
) -> List[CallSite]:
    """Approximate call sites for non-Python languages.

    Caller attribution uses the nearest preceding definition line.

    Args:
        file_id: Relative file identifier.
        content: Full file content.
        symbols: Definitions for caller attribution.

    Returns:
        Call sites in source order.
    """
    sites: List[CallSite] = []
    ordered = sorted(symbols, key=lambda s: s.line)
    for lineno, line in enumerate(content.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith(("#", "//", "*", "/*", "<!--")):
            continue
        caller = ""
        for symbol in ordered:
            if symbol.line <= lineno:
                caller = symbol.name
            else:
                break
        for match in _CALL_RE.finditer(line):
            name = match.group(1)
            if _DEF_RE.match(line) and name in {s.name for s in ordered}:
                continue
            before = _RECEIVER_RE.search(line[max(0, match.start(1) - int(self._config.SYMINDEX_RECEIVER_WINDOW)):match.start(1)])
            sites.append(
                CallSite(
                    file=file_id, caller=caller, callee=name,
                    line=lineno, column=match.start(1),
                    receiver=before.group(1) if before else "",
                )
            )

def __init__(self, config: Config) -> None:
    self._config = config
    self._severity_map: Dict[str, str] = dict(self.SEVERITIES)

def _find_direct_sources(
    self, nodes: List[Node], edges: List[Edge]
) -> Dict[str, List[str]]:
    """Find files that directly import known-dangerous modules."""
    source_map: Dict[str, List[str]] = {}
    node_ids: Set[str] = {n.node_id for n in nodes}

    all_rules: Dict[str, str] = {}
    for lang_rules in self.DANGEROUS_IMPORTS_BY_LANGUAGE.values():
        all_rules.update(lang_rules)

    for edge in edges:
        if edge.relation != "imports":
            continue
        if edge.source not in node_ids:
            continue
        target_lower = edge.target.lower()
        for dangerous_key, _description in all_rules.items():
            if dangerous_key in target_lower:
                if edge.source not in source_map:
                    source_map[edge.source] = []
                source_map[edge.source].append(dangerous_key)
                break

    return source_map

def _propagate(
    self,
    source_node_id: str,
    danger_import: str,
    adj: Dict[str, Set[str]],
    nodes: List[Node],
    max_depth: int,
) -> List[TaintPath]:
    """BFS propagation from source through the import graph."""
    node_ids: Set[str] = {n.node_id for n in nodes}
    if source_node_id not in adj:
        return []

    paths: List[TaintPath] = []
    visited: Set[str] = {source_node_id}
    queue: deque = deque()
    queue.append((source_node_id, [source_node_id], 0))

    while queue and len(paths) < self._config.TAINT_MAX_PATHS:
        current, path, depth = queue.popleft()
        if depth >= max_depth:
            continue
        for neighbor in adj.get(current, set()):
            if neighbor not in node_ids:
                continue
            if neighbor in visited and neighbor != source_node_id:
                continue
            visited.add(neighbor)
            new_path = path + [neighbor]
            severity = self._severity_map.get(
                danger_import,
                self._severity_map.get(
                    danger_import.split(".")[0], "medium"
                ),
            )
            paths.append(
                TaintPath(
                    source_file=source_node_id,
                    sink_file=neighbor,
                    path=list(new_path),

def _build_forward_graph(
    nodes: List[Node], resolved_edges: List[Edge]
) -> Dict[str, Set[str]]:
    """Build a forward-directed import graph from resolved edges."""
    adj: Dict[str, Set[str]] = {}
    file_ids: Set[str] = {n.node_id for n in nodes}
    for edge in resolved_edges:
        if edge.source in file_ids and edge.target in file_ids:
            if edge.source not in adj:
                adj[edge.source] = set()
            adj[edge.source].add(edge.target)
    return adj

def render_mermaid_class_diagram(
    self,
    nodes: List[Node],
    edges: List[Edge],
) -> str:
    class_nodes: List[tuple] = []
    for node in nodes:
        for sym in node.symbols:
            if sym.kind in _CLASS_LIKE_KINDS:
                class_nodes.append((node, sym))
    if not class_nodes:
        return ""

    max_classes = self._config.UML_MAX_CLASSES
    if len(class_nodes) > max_classes:
        class_nodes = class_nodes[:max_classes]

    lines: List[str] = ["classDiagram", "  direction LR"]
    class_ids: Set[str] = set()

    for node, sym in class_nodes:
        class_id = self._sanitize_id(f"{node.label}_{sym.name}")
        class_ids.add(class_id)

        lines.append(f"  class {class_id} {{")
        lines.append(f"    <<{sym.kind}>>")

        methods = [
            s for s in node.symbols
            if s.kind in ("function", "method")
        ]
        for method in methods[:10]:
            params = ""
            if method.signature:
                sig = method.signature
                paren = sig.find("(")
                if paren >= 0:
                    params = sig[paren:].rstrip("{: ")
            lines.append(f"    +{method.name}{params}")

def generate_code(
    self,
    nodes: List[Node],
    edges: List[Edge],
    target_language: str,
) -> str:
    target = target_language.lower().lstrip("-")
    if target not in _LANGUAGE_CODE_GENERATORS:
        return f"// Unknown target language: {target_language}"

    generator = _get_code_generator(target)
    class_symbols: List[tuple] = []
    for node in nodes:
        for sym in node.symbols:
            if sym.kind in _CLASS_LIKE_KINDS:
                methods = [
                    s for s in node.symbols
                    if s.kind in ("function", "method")
                ]
                class_symbols.append((node, sym, methods))

    return generator(class_symbols, nodes, edges)

@staticmethod

def _sanitize_id(raw: str) -> str:
    sanitized = ""
    for ch in raw:
        if ch.isalnum() or ch == "_":
            sanitized += ch
        else:
            sanitized += "_"
    if sanitized and sanitized[0].isdigit():
        sanitized = "n_" + sanitized
    return sanitized

@staticmethod

def _find_node(nodes: List[Node], node_id: str) -> Optional[Node]:
    for n in nodes:
        if n.node_id == node_id:
            return n
    return None

