def _extract_docstring(self, line_num: int) -> str:
    """Walk backwards from *line_num* to collect preceding comments/docstrings.

    Supports ``//``, ``///``, ``//!``, ``#``, ``/* */``, and ``/** */``
    comment styles. Limits lookback to ``DOCSTRING_LOOKBACK_LINES``
    from Config.
    """
    if line_num >= len(self.lines):
        return ""
    doc_lines: List[str] = []
    in_block_comment = False
    max_lookback = self.config.DOCSTRING_LOOKBACK_LINES
    for i in range(line_num - 1, max(-1, line_num - max_lookback), -1):
        line = self.lines[i].strip()
        if not line:
            if not in_block_comment:
                break
            continue
        if line.endswith("*/"):
            in_block_comment = True
            doc_lines.insert(0, line.rstrip("*/").strip())
            continue
        if in_block_comment:
            cleaned = line.lstrip("/*").lstrip("*").strip()
            doc_lines.insert(0, cleaned)
            if line.startswith("/*") or line.startswith("/**"):
                break
            continue
        if line.startswith("///") or line.startswith("//!"):
            doc_lines.insert(0, line[3:].strip())
        elif line.startswith("//"):
            doc_lines.insert(0, line[2:].strip())
        elif line.startswith("#") and not line.startswith("#!"):
            doc_lines.insert(0, line[1:].strip())
        elif line == "":
            continue
        else:
            break

def _extract_signature(self, content: str, match_start: int, pattern: str) -> str:
    """Extract a compact signature snippet starting at *match_start*.

    Scans forward to the opening brace or a fallback length,
    then truncates to 100 characters for display.
    """
    start = match_start
    end = content.find("{", start)
    if end == -1:
        end = start + 120
    raw = content[start:end].strip()
    if len(raw) > 100:
        raw = raw[:97] + "..."
    return raw

def _has_type_prefix(prefix: str) -> bool:
    """Return True when a prototype prefix carries a return type."""
    tokens = re.findall(r"[A-Za-z_]\w*|\*|&", prefix)
    for tok in tokens:
        if tok in ("*", "&"):
            return True
        if tok in _PROTO_TYPE_WORDS or tok.endswith("_t"):
            return True
    return False

def _extract_specifics(self, content: str) -> None:
    """Extract C-family symbols and imports from source content.

    Collects includes (quoted vs system), structs, classes, enums,
    unions, typedefs, functions (definitions and prototypes), extern
    declarations, globals, and macros.
    """
    lines = content.split("\n")
    in_block_comment = False
    active_code_lines: list[str] = []
    for raw in lines:
        code = raw
        if in_block_comment:
            end = code.find("*/")
            if end < 0:
                active_code_lines.append("")
                continue
            code = code[end + 2 :]
            in_block_comment = False
        while "/*" in code:
            start = code.find("/*")
            end = code.find("*/", start + 2)
            if end < 0:
                code = code[:start]
                in_block_comment = True
                break
            code = code[:start] + code[end + 2 :]
        stripped = code.split("//")[0]
        active_code_lines.append(stripped)
    active = "\n".join(active_code_lines)
    in_if0 = False
    for raw_line in active.split("\n"):
        s = raw_line.strip()
        if s.startswith("#"):
            if s.startswith("#if 0") or s.startswith("#if\t0"):
                in_if0 = True
                continue
            if s.startswith("#endif"):
                in_if0 = False
                continue

